define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_69.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e227230","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_74.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e227334","topics":[]},{"title":"Applying LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier_14.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e227438","topics":[]},{"title":"Removing the Global Operator Cabinet Audio Assembly (GOCAA)","shortdesc":"<p class=\"shortdesc\">Instructions for removing the Global Operator Cabinet Audio Assembly (GOCAA).<\/p>","href":"t_RemovingTheGOCAudioAssembly.html","attributes":{"data-id":"id_2012508"},"menu":{"hasChildren":false},"tocID":"id_2012508-d46e227542","topics":[]},{"title":"Installing the Global Operator Cabinet Audio Assembly (GOCAA)","shortdesc":"<p class=\"shortdesc\">Instructions for installing the Global Operator Cabinet Audio Assembly (GOCAA).<\/p>","href":"t_InstallingTheGOCAudioAssembly.html","attributes":{"data-id":"id_2001807"},"menu":{"hasChildren":false},"tocID":"id_2001807-d46e227646","topics":[]},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier_14.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e227750","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_73.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e227854","topics":[]},{"title":"Completing the Global Operator Cabinet Audio Assembly (GOCAA) installation","shortdesc":"<p class=\"shortdesc\">Global Operator Cabinet Audio Assembly (GOCAA) install adjustment and final steps.<\/p>","href":"t_CompletingTheGOCAudioAssemblyInstallation.html","attributes":{"data-id":"id_2015034"},"menu":{"hasChildren":false},"tocID":"id_2015034-d46e227958","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_94.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e228062","topics":[]}]});